@push('scripts')
<script>
const cf=document.getElementById('conversion-form'),preview=document.getElementById('conversion-preview'),pb=document.getElementById('preview-conversion'),cb=document.getElementById('confirm-conversion');let ready=false;
function payload(){return Object.fromEntries(new FormData(cf).entries());}
pb.addEventListener('click',async()=>{pb.disabled=true;ready=false;cb.disabled=true;try{const q=await window.shellAjax(@json(route('convert.quote')),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload())});cf.elements.source_quote_at.value=q.source_quote_at||'';cf.elements.target_quote_at.value=q.target_quote_at||'';document.getElementById('conversion-output').textContent=q.amount_out+' '+q.to_currency;document.getElementById('conversion-details').textContent='Rate basis: '+q.source_price+' USDT per '+q.from_currency+' / '+q.target_price+' USDT per '+q.to_currency+'. No fee is applied; no real asset is moved.';preview.hidden=false;ready=true;cb.disabled=false;}catch(e){window.shellToast(e.message,'error');preview.hidden=true;}finally{pb.disabled=false;}});
cb.addEventListener('click',async()=>{if(!ready)return;cb.disabled=true;try{const r=await window.shellAjax(@json(route('convert.paper')),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload())});window.shellToast(r.message);window.location.reload();}catch(e){window.shellToast(e.message,'error');ready=false;preview.hidden=true;}finally{cb.disabled=false;}});
cf.addEventListener('input',()=>{ready=false;preview.hidden=true;});
</script>
@endpush